ALTER TABLE public.tg_users ADD COLUMN IF NOT EXISTS referral_earned numeric NOT NULL DEFAULT 0;
CREATE UNIQUE INDEX IF NOT EXISTS withdrawals_fee_unique ON public.withdrawals(fee_tx) WHERE fee_tx IS NOT NULL;
CREATE OR REPLACE FUNCTION public.orange_mining_claim(p_user_id bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE u public.tg_users; elapsed numeric; reward numeric; ts timestamptz := now(); BEGIN SELECT * INTO u FROM public.tg_users WHERE id=p_user_id FOR UPDATE; IF u.mining_started_at IS NULL THEN RAISE EXCEPTION 'Not mining'; END IF; IF ts < u.mining_started_at + interval '2 hours' THEN RAISE EXCEPTION 'Mining not finished'; END IF; elapsed := greatest(0, extract(epoch from (least(ts,u.mining_started_at + interval '2 hours') - coalesce(u.mining_settled_at,u.mining_started_at)))); reward := u.mining_pending + elapsed / 86400 * u.mining_rate_daily; UPDATE public.tg_users SET balance=balance+reward, mining_started_at=ts, mining_settled_at=ts, mining_pending=0 WHERE id=p_user_id; IF u.referred_by IS NOT NULL AND u.referred_by<>p_user_id THEN UPDATE public.tg_users SET balance=balance+reward*0.10, referral_earned=referral_earned+reward*0.10 WHERE id=u.referred_by; END IF; RETURN jsonb_build_object('balance',u.balance+reward,'mining_started_at',ts); END $$;
REVOKE ALL ON FUNCTION public.orange_mining_claim(bigint) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.orange_mining_claim(bigint) TO service_role;
CREATE OR REPLACE FUNCTION public.orange_reserve_withdrawal(p_user_id bigint,p_amount numeric,p_fee text,p_address text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w uuid; BEGIN IF p_amount<100 THEN RAISE EXCEPTION 'Minimum is 100 ORAI'; END IF; UPDATE public.tg_users SET balance=balance-p_amount WHERE id=p_user_id AND balance>=p_amount; IF NOT FOUND THEN RAISE EXCEPTION 'Not enough ORAI'; END IF; INSERT INTO public.withdrawals(user_id,amount,to_address,fee_tx,status) VALUES(p_user_id,p_amount,p_address,p_fee,'pending') RETURNING id INTO w; RETURN w; END $$;
REVOKE ALL ON FUNCTION public.orange_reserve_withdrawal(bigint,numeric,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.orange_reserve_withdrawal(bigint,numeric,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.orange_refund_withdrawal(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w public.withdrawals; BEGIN SELECT * INTO w FROM public.withdrawals WHERE id=p_id FOR UPDATE; IF w.status='pending' THEN UPDATE public.tg_users SET balance=balance+w.amount WHERE id=w.user_id; UPDATE public.withdrawals SET status='failed' WHERE id=p_id; END IF; END $$;
REVOKE ALL ON FUNCTION public.orange_refund_withdrawal(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.orange_refund_withdrawal(uuid) TO service_role;